#!/usr/bin/env bash
set -euo pipefail

HOST="${TSP_HOST:-root@192.168.1.21}"
DL_DIR="${HOME}/Downloads"
STAMP="$(date +%Y%m%d-%H%M%S)"
SOCK="${TMPDIR:-/tmp}/tsp-openmw-${USER:-user}-$$.sock"
LOCAL_BASE="$(mktemp)"
ARCHIVE="$DL_DIR/tsp_failed_diag_before_restore_${STAMP}.tar"

cleanup() {
  ssh -S "$SOCK" -O exit "$HOST" >/dev/null 2>&1 || true
  rm -f "$SOCK" "$LOCAL_BASE"
}
trap cleanup EXIT

printf '%s\n' '===== 1/5 AUTHENTICATE ONCE ====='
printf '%s\n' 'Enter the TSP root password once. Every remaining SSH operation reuses this connection.'
ssh -o ControlMaster=yes -o ControlPersist=10m -o ControlPath="$SOCK" -Nf "$HOST"

printf '%s\n' '===== 2/5 FIND ACTIVE LAUNCHER + OPENMW ROOT ====='
REMOTE_INFO="$(ssh -S "$SOCK" "$HOST" 'sh -s' <<'EOF_REMOTE'
set -e
PLAY=""
for p in \
  /roms/ports/Morrowind.sh \
  /mnt/mmc/ROMS/Ports/Morrowind.sh \
  /mnt/mmc/ROMS/PORTS/Morrowind.sh \
  /mnt/SDCARD/Roms/PORTS/Morrowind.sh \
  /mnt/sdcard/mmcblk1p1/Roms/PORTS/Morrowind.sh \
  /userdata/roms/ports/Morrowind.sh \
  /storage/roms/ports/Morrowind.sh
 do
  if [ -f "$p" ]; then PLAY="$p"; break; fi
 done
ROOT=""
for r in \
  /mnt/SDCARD/data/ports/openmw \
  /mnt/sdcard/mmcblk1p1/data/ports/openmw \
  /userdata/roms/ports/openmw \
  /mnt/mmc/ports/openmw \
  /mnt/sdcard/ports/openmw \
  /roms/ports/openmw \
  /storage/roms/ports/openmw
 do
  if [ -x "$r/bin/openmw-0.51" ]; then ROOT="$r"; break; fi
 done
[ -n "$PLAY" ] || { echo 'ERROR: active Morrowind.sh not found' >&2; exit 20; }
[ -n "$ROOT" ] || { echo 'ERROR: OpenMW root not found' >&2; exit 21; }
printf 'PLAY=%s\nROOT=%s\n' "$PLAY" "$ROOT"
EOF_REMOTE
)"
printf '%s\n' "$REMOTE_INFO"
PLAY="$(printf '%s\n' "$REMOTE_INFO" | sed -n 's/^PLAY=//p' | head -n1)"
ROOT="$(printf '%s\n' "$REMOTE_INFO" | sed -n 's/^ROOT=//p' | head -n1)"
[ -n "$PLAY" ] && [ -n "$ROOT" ]

printf '%s\n' '===== 3/5 PRESERVE THE FAILED DIAGNOSTIC RUN ====='
if ssh -S "$SOCK" "$HOST" "ROOT='$ROOT' sh -s" <<'EOF_REMOTE' > "$ARCHIVE"
set -e
cd "$ROOT"
set --
[ -d tsp_diag/latest ] && set -- "$@" tsp_diag/latest
[ -f openmw_log.txt ] && set -- "$@" openmw_log.txt
[ -f openmw_051_log.txt ] && set -- "$@" openmw_051_log.txt
[ -f config/openmw.log ] && set -- "$@" config/openmw.log
[ -f openmw_perf_latest.txt ] && set -- "$@" openmw_perf_latest.txt
[ "$#" -gt 0 ] || exit 44
exec tar -cf - "$@"
EOF_REMOTE
then
  if tar -tf "$ARCHIVE" >/dev/null 2>&1; then
    echo "Saved failed-run evidence: $ARCHIVE"
  else
    echo 'WARNING: returned archive did not validate; removing it.' >&2
    rm -f "$ARCHIVE"
  fi
else
  rc=$?
  rm -f "$ARCHIVE"
  if [ "$rc" -eq 44 ]; then
    echo 'No diagnostic/log files were present to collect. Continuing with restore.'
  else
    echo "WARNING: diagnostic collection failed with rc=$rc. Continuing with restore." >&2
  fi
fi

printf '%s\n' '===== 4/5 RESTORE THE EXACT WATCHDOG BASELINE ====='
base64 -d > "$LOCAL_BASE" <<'BASE64_EOF'
IyEvYmluL2Jhc2gKIyA+Pj4gVFNQX1FVSUVUX1YxIEJFR0lOCiMgU2hpcHBpbmc6IGV2ZXJ5IHBy
