chmod +x "$LOCAL_BASE"
LOCAL_SHA="$(sha256sum "$LOCAL_BASE" | awk '{print $1}')"
EXPECTED_SHA='8b6a3129bf37e5c39b0bee8572214ec72f32b8f750f7dd5b3910acd266ef1d38'
[ "$LOCAL_SHA" = "$EXPECTED_SHA" ] || {
  echo "ERROR: embedded baseline SHA mismatch: $LOCAL_SHA != $EXPECTED_SHA" >&2
  exit 30
}

BACKUP="$ROOT/launcher-backups/Morrowind.sh.before-diag-rollback-$STAMP"
ssh -S "$SOCK" "$HOST" "mkdir -p '$ROOT/launcher-backups' && cp -p '$PLAY' '$BACKUP'"
echo "Backup: $BACKUP"
ssh -S "$SOCK" "$HOST" "cat > '$PLAY.restore-new'" < "$LOCAL_BASE"
ssh -S "$SOCK" "$HOST" "chmod +x '$PLAY.restore-new' && bash -n '$PLAY.restore-new' && mv -f '$PLAY.restore-new' '$PLAY'"

printf '%s\n' '===== 5/5 VERIFY EXACT FILE + WATCHDOG/PERF MARKERS ====='
REMOTE_SHA="$(ssh -S "$SOCK" "$HOST" "sha256sum '$PLAY' | awk '{print \\$1}'")"
[ "$REMOTE_SHA" = "$EXPECTED_SHA" ] || {
  echo "ERROR: device launcher SHA mismatch: $REMOTE_SHA != $EXPECTED_SHA" >&2
  exit 31
}
ssh -S "$SOCK" "$HOST" "grep -Fq 'openmw-muos-audio-watchdog-clean-2026-09-16-v1' '$PLAY' && grep -Fq 'TSP_RINGARM_V2' '$PLAY' && grep -Fq 'TSP_PERF_SAMPLER_V1' '$PLAY' && grep -Fq 'TSP_MUOS_AUDIO_V2' '$PLAY'"

echo "PASS: restored exact uploaded watchdog launcher"
echo "sha256=$REMOTE_SHA"
echo "PLAY=$PLAY"
echo "ROOT=$ROOT"
echo 'No OpenMW binary, libGL, configs, mods, or saves were changed.'
if [ -f "$ARCHIVE" ]; then echo "Failed-run evidence: $ARCHIVE"; fi
